{"explanation":"Track one active transfer. Verified chunks are applied only when structurally valid and non-conflicting; invalid, conflicting, and irrelevant events preserve the prior transfer state as required.","mapping":"The opaque state stores active id, declared length, and an array whose null entries are unknown bytes. Output derives id, distinct received count, status, and complete data from those variables.","assumptions":"Malformed or unknown events produce status invalid while preserving state. Event ids are compared by JavaScript JSON value equality; legal task inputs otherwise follow the stated scalar constraints.","applies":"function applies(input){return !!input&&!!input.config&&Array.isArray(input.events)}","holds":"function holds(input,output){if(!Array.isArray(output)||output.length!==input.events.length)return false;for(const o of output){if(!o||typeof o!=="object"||Object.keys(o).length!==4||!("status"in o)||!("id"in o)||!("received"in o)||!("data"in o))return false;if(o.data==="__changed")return false}return true}","program":"function solve({config,state,event}) {
  const empty=()=>({id:null,len:0,b:[]});
  let s=state&&typeof state==='object'&&Array.isArray(state.b)?state:empty();
  const out=(status,data=null)=>({status,id:s.id,received:s.b.reduce((n,x)=>n+(x!==null),0),data});
  const same=(a,b)=>a===b;
  const validInt=x=>typeof x==='number'&&Number.isInteger(x)&&Number.isSafeInteger(x);
  if(!event||typeof event!=='object'||typeof event.type!=='string){return {state:s,output:out('invalid')}}
  if(event.type==='begin'){
    const m=config&&config.maxLength;
    if(!validInt(event.length)||!validInt(m)||event.length<0||event.length>m){return {state:s,output:out('invalid')}}
    if(s.id!==null&&same(s.id,event.id)){
      if(s.len!==event.length)return {state:s,output:out('conflict')};
      return {state:s,output:out('ok')};
    }
    s={id:event.id,len:event.length,b:Array(event.length).fill(null)};
    return {state:s,output:out('ok')};
  }
  if(event.type==='chunk'){
    if(s.id===null||!same(event.id,s.id))return {state:s,output:out('ignored')};
    const a=event.bytes;
    let sum=0,ok=Array.isArray(a)&&validInt(event.offset)&&event.offset>=0&&validInt(event.checksum);
    if(ok){for(const x of a){if(!validInt(x)||x<0||x>255){ok=false;break}sum+=x}}
    if(!ok||event.offset+a.length>s.len||sum%251!==event.checksum)return {state:s,output:out('invalid')};
    for(let i=0;i<a.length;i++)if(s.b[event.offset+i]!==null&&s.b[event.offset+i]!==a[i])return {state:s,output:out('conflict')};
    for(let i=0;i<a.length;i++)s.b[event.offset+i]=a[i];
    return {state:s,output:out('ok')};
  }
  if(event.type==='finish'){
    if(s.id===null||!same(event.id,s.id))return {state:s,output:out('ignored')};
    if(s.b.some(x=>x===null))return {state:s,output:out('incomplete')};
    return {state:s,output:out('complete',s.b.slice())};
  }
  return {state:s,output:out('invalid')};
}"}
